// Check if username is set in session
if (isset($_SESSION['username'])) {
    $username = $_SESSION['username'];

    // Check if the username is a burger-id (ends with '-DK')
    if (strpos($username, '-DK') !== false) {
        echo 
"  <li class=\"user-id\">Bruger-id:
    <span class=\"id\">
    <form method=\"POST\" novalidate action=\"/profil/skift_adgangskode\">
    
    <select name=\"dkhmsb_shift_userid\" class=\"md-arrow select-small on_change_submit_form\">
    <option selected value=\"$username\">$username</option>
    </select>
    <noscript><input type=\"submit\" class=\"button button-secondary button-small\" value=\"Skift\"></noscript>
    </form>
    </span>
    </li>";

    // Check if the username is a valid email
    } elseif (filter_var($username, FILTER_VALIDATE_EMAIL)) {
        echo 
"  <li class=\"user-id\">E-mail:
    <span class=\"id\">
    <form method=\"POST\" novalidate action=\"/profil/skift_adgangskode\">
    
    <select name=\"dkhmsb_shift_userid\" class=\"md-arrow select-small on_change_submit_form\">
    <option selected value=\"$username\">$username</option>
    </select>
    <noscript><input type=\"submit\" class=\"button button-secondary button-small\" value=\"Skift\"></noscript>
    </form>
    </span>
    </li>";

    // Check if the username is a domain name (e.g., 'example.com')
    } elseif (preg_match('/^([a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}$/', $username)) {
        echo 
"  <li class=\"user-id\">domænenavn:
    <span class=\"id\">
    <form method=\"POST\" novalidate action=\"/profil/skift_adgangskode\">
    
    <select name=\"dkhmsb_shift_userid\" class=\"md-arrow select-small on_change_submit_form\">
    <option selected value=\"$username\">$username</option>
    </select>
    <noscript><input type=\"submit\" class=\"button button-secondary button-small\" value=\"Skift\"></noscript>
    </form>
    </span>
    </li>";

    } else {
        echo "Unknown identifier type.";
    }
} else {
    echo "No user data found.";
}
